<?php
$prefixes=array('/huawei'=>'huawei','/baidu'=>'baidu','/west'=>'west');$uri=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$provider='';foreach($prefixes as $p=>$v){if(strpos($uri,$p)===0){$provider=$v;$uri=substr($uri,strlen($p));break;}}if($uri==='/__reset'){file_put_contents(sys_get_temp_dir().'/g2_state.json',json_encode(array('records'=>array(),'next'=>1)));header('Content-Type: application/json');echo '{}';exit;}$stateFile=sys_get_temp_dir().'/g2_state.json';if(!file_exists($stateFile))file_put_contents($stateFile,json_encode(array('records'=>array(),'next'=>1)));$st=json_decode(file_get_contents($stateFile),true);$auth=isset($_SERVER['HTTP_AUTHORIZATION'])?$_SERVER['HTTP_AUTHORIZATION']:'';if($provider==='huawei'&&strpos($auth,'SDK-HMAC-SHA256 Access=')!==0){http_response_code(401);echo json_encode(array('error_code'=>'APIGW.0301','error_msg'=>'auth failed'));exit;}if($provider==='baidu'&&strpos($auth,'bce-auth-v1/')!==0){http_response_code(403);echo json_encode(array('code'=>'AccessDenied','message'=>'auth failed'));exit;}if($provider==='west'&&!isset($_POST['token'])&&$_SERVER['REQUEST_METHOD']==='POST'){http_response_code(401);echo json_encode(array('result'=>401,'msg'=>'auth failed'));exit;}header('Content-Type: application/json');$m=$_SERVER['REQUEST_METHOD'];$parts=explode('/',trim($uri,'/'));if($provider==='huawei'){if($uri==='/v2/zones'){echo json_encode(array('zones'=>array(array('id'=>'z1','name'=>'example.com.','record_num'=>0))));exit;}if(strpos($uri,'/v2.1/zones/')===0){$id=end($parts);if($m==='GET')echo json_encode(array('recordsets'=>array_values($st['records'])));elseif($m==='POST'||$m==='PUT'){ $body=json_decode(file_get_contents('php://input'),true);$body['id']=isset($body['id'])?$body['id']:'r'.$st['next']++;$st['records'][$body['id']]=$body;file_put_contents($stateFile,json_encode($st));echo json_encode($body);}elseif($m==='DELETE'){unset($st['records'][$id]);file_put_contents($stateFile,json_encode($st));echo '{}';}exit;}}if($provider==='baidu'){if($uri==='/v1/dns/zone'){echo json_encode(array('zones'=>array(array('name'=>'example.com','recordCount'=>0))));exit;}if(strpos($uri,'/v1/dns/zone/')===0){$id=end($parts);if($m==='GET')echo json_encode(array('records'=>array_values($st['records'])));elseif($m==='POST'||$m==='PUT'){ $body=json_decode(file_get_contents('php://input'),true);$body['id']=isset($body['id'])?$body['id']:'r'.$st['next']++;$st['records'][$body['id']]=$body;file_put_contents($stateFile,json_encode($st));echo json_encode($body);}elseif($m==='DELETE'){unset($st['records'][$id]);file_put_contents($stateFile,json_encode($st));echo '{}';}exit;}}if($provider==='west'){if(isset($_GET['act'])&&$_GET['act']==='getdomains')echo json_encode(array('result'=>200,'data'=>array(array('domain'=>'example.com'))));else echo json_encode(array('result'=>200,'data'=>array()));exit;}http_response_code(404);echo json_encode(array('code'=>'NotFound'));
